import os

def sum_totals(directory):
    total_sum = 0
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r') as f:
                    for line in f:
                        if line.startswith('TOTAL:'):
                            number_str = line.split(':', 1)[1].strip()
                            total_sum += int(number_str)
                            break
            except Exception:
                continue
    return total_sum

